/*
 * Inventory fixtures built from the synthetic Quicken exports in `qif-corpus/`
 * (generated by `qif-corpus/generate-corpus.mjs`), one entry per account.
 *
 * The corpus deliberately keeps a real collection's collision density: many
 * coins sharing a year and denomination, differing only by grade. Regenerating
 * it with one coin per (year, denomination) would leave the matcher tests
 * passing while testing very little.
 *
 * It also carries synthetic versions of the sections the importer ignores
 * (`!Type:Prices`, `!Type:Security`, `!Type:Cat`, `!Type:Tag`, `!Type:Bank`,
 * `NXIn`/`NXOut` transfers, `!Option:` markers) so the ignoring stays tested.
 *
 * The files are windows-1252, not UTF-8: "¢" is byte 0xA2 and "½" is 0xBD.
 *
 * `Ancients.QIF` is excluded: ancient coins have no year, denomination or grade
 * and are matched on catalogue references instead (see
 * `docs/ancients-matching-plan.md`).
 */

import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { CoinRecord } from '../types/coin.model';
import { QuickenImportService } from '../services/quicken-import.service';

/** The corpus directory, resolved from this file so it works from any working directory. */
const CORPUS_DIR = resolve(dirname(fileURLToPath(import.meta.url)), 'qif-corpus');

/** One Quicken account, and what is special about it. */
export interface QifAccount {
  /** The `.QIF` file in `qif-corpus/`. */
  file: string;
  /** The account name from the `!Account` block's `N` line; passed to `QuickenImportService.parse`. */
  account: string;
  /** What this account exercises that the others do not; printed in the census. */
  why: string;
}

