/** Read a `.QIF` from `qif-corpus/` with the same windows-1252 decoder the import modal uses. */
export function decodeQif(file: string): string {
  return new TextDecoder('windows-1252').decode(readFileSync(resolve(CORPUS_DIR, file)));
}

/**
 * Every distinct raw security name filed under one account, in file order.
 * Includes sold coins (which `parse` would skip under the net-quantity rule),
 * since they make the inventory denser. Scanned directly because the service
 * does not expose raw names, and the filename builders need the original text.
 */
export function securityNamesFor(account: QifAccount): string[] {
  const names: string[] = [];
  const seen = new Set<string>();

  let inAccountBlock = false;
  let currentAccount: string | null = null;
  let inInvestmentSection = false;

  for (const raw of decodeQif(account.file).split(/\r?\n/)) {
    // QIF is CRLF and the final field of every block is a bare "^".
    const line = raw.trimEnd();

    if (line.startsWith('!Account')) {
      // The next `N` line names the account.
      inAccountBlock = true;
      inInvestmentSection = false;
      continue;
    }
    if (line.startsWith('!Type:')) {
      // A `!Type:Invst` header applies to the account most recently named.
      inAccountBlock = false;
      inInvestmentSection = line.startsWith('!Type:Invst');
      continue;
    }
    if (inAccountBlock && line.startsWith('N')) {
      currentAccount = line.slice(1).trim();
      continue;
    }

    // `Y` is the security name on an investment transaction.
    if (inInvestmentSection && currentAccount === account.account && line.startsWith('Y')) {
      const name = line.slice(1).trim();
      if (name && !seen.has(name)) {
        seen.add(name);
        names.push(name);
      }
    }
  }

  return names;
}

/**
 * Turn an account's security names into coin records by running them through
 * the real importer, so the fixture follows any change in field mapping. Each
 * name is wrapped in a one-share purchase so the net-quantity rule keeps it.
 */
export function inventoryFor(account: QifAccount): CoinRecord[] {
  const qif =
    '!Type:Invst\n' +
    securityNamesFor(account)
      .map(name => `D01/15/2024\nNBuy\nY${name}\nQ1\nT100.00\n^`)
      .join('\n') +
    '\n';

  const records = new QuickenImportService().parse(qif).importedRecords as unknown as CoinRecord[];

  // Importer ids are not stable across runs; assign predictable ones.
  records.forEach((record, index) => {
    record.id = `${account.account}-${index}`;
    record.imagePaths = [];
  });
  return records;
}

/**
 * The grade as typically written in a filename: "PF64 Cameo" -> "PF64CAM" and
 * "PR65" -> "PF65" (PCGS prints PR, NGC prints PF). Everything else passes through.
 */
export function filenameGrade(recordGrade: string): string {
  return recordGrade
    .replace(/\s*Cameo\b/gi, 'CAM')
    .replace(/\bPR(?=\d)/g, 'PF');
}

/**
 * The photograph "stem" for one security (everything before " - Obverse").
 * Built from the raw security text, since real filenames keep its separators.
 * Only three changes: "/CAC" is dropped (not used in filenames), the grade is
 * respelled via `filenameGrade`, and "/" becomes "-" because Windows forbids
 * "/" in filenames (e.g. overdates like "1887/6").
 */
export function photoStem(security: string): string {
  return filenameGrade(security.replace(/\/CAC/gi, ''))
    .replace(/\//g, '-')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Photograph names for a whole account: one per coin per side (obverse and reverse by default). */
export function photoFilenamesFor(
  account: QifAccount,
  sides: readonly string[] = ['Obverse', 'Reverse']
): string[] {
  const names: string[] = [];
  for (const security of securityNamesFor(account)) {
    for (const side of sides) {
      names.push(`${photoStem(security)} - ${side}.jpg`);
    }
  }
  return names;
}

/**
 * One deliberately uninformative extra photo per coin: year, mint mark and
 * denomination only (e.g. "1870 10-cent - Obverse.jpg"). A filename without
 * "Proof" implies a business strike, so these must not match proof records;
 * this lets the census measure that rule. Built from the imported record;
 * coins missing a year or denomination are skipped.
 */
export function silentPhotoFilenamesFor(account: QifAccount): string[] {
  const names: string[] = [];
  for (const record of inventoryFor(account)) {
    if (!record.year || !record.denomination) continue;
    const yearPart = [record.year, record.mintMark].filter(Boolean).join('-');
    names.push(`${yearPart} ${record.denomination} - Obverse 2.jpg`.replace(/\//g, '-'));
  }
  return [...new Set(names)];
}
